import * as E from './engine.js';import {GAME}from'./config.js';import {Battlefield,ready}from'./scene-classic.js';import {PeerRoom,rosterFromSave}from'./multiplayer.js';
const $=s=>document.querySelector(s);let main;try{const raw=localStorage.getItem(GAME.id+'-campaign-v1');main=raw?E.decode(raw,Date.now(),false):E.createIslandState(341);}catch{main=E.createIslandState(341);}let roster=rosterFromSave(main);if(!roster.length)roster=Array.from({length:6},()=>({type:'rifle',level:1,hp:E.UNITS.rifle.hp}));
$('#roster-summary').textContent=roster.length+' tropas en la copia de duelo. Se comparten únicamente sus tipos, grados y vida; no se envían los recursos, el mapa ni tu archivo de guardado.';let room=null,selected=[],mode='move',state=E.createIslandState(341),lastUi=0,lastFrame=0;await ready;const scene=new Battlefield($('#duel-world'),pick);scene.state=state;scene.home(state);$('#connection-status').textContent='Sin conectar';
function message(text){$('#room-message').textContent=text;$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(message.timer);message.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function own(u){return u.owner===room?.role&&u.hp>0;}
let abilityMode=null;const skillsBar=document.createElement('section');skillsBar.id='duel-skills';skillsBar.hidden=true;$('#duel-field').append(skillsBar);
function renderSkills(){if(!state.battle||!room)return;const side=room.role==='host'?'player':'enemy',skills=E.availableAbilities(state,selected,side),budget=state.network.budgets[room.role],signature=JSON.stringify([selected,abilityMode,skills.map(a=>[a.id,a.ready,Math.ceil(a.remaining)]),budget]);skillsBar.hidden=!skills.length;if(skillsBar.dataset.signature===signature)return;skillsBar.dataset.signature=signature;skillsBar.replaceChildren();const text=document.createElement('small');text.textContent=abilityMode?'Marca un objetivo cercano en el mapa.':'Apoyo: '+Math.floor(budget.supply)+' petróleo · '+Math.floor(budget.metal)+' acero';skillsBar.append(text);for(const a of skills){const button=document.createElement('button');button.textContent=a.name+(a.ready?'':' · '+Math.ceil(a.remaining)+' s');button.title=a.description;button.disabled=!a.ready;button.addEventListener('click',()=>{const u=state.battle.units.find(u=>u.id===a.caster);if(!u)return;if(a.range===0){room.command({kind:'ability',ids:selected,ability:a.id,x:u.x,y:u.y});}else{abilityMode=a.id;message(a.name+': marca una zona a su alcance.');}renderSkills();});skillsBar.append(button);}if(abilityMode){const cancel=document.createElement('button');cancel.textContent='Cancelar';cancel.addEventListener('click',()=>{abilityMode=null;renderSkills();});skillsBar.append(cancel);}}
function center(){const b=state.battle,base=b?.buildings.find(v=>v.owner===room?.role&&v.type==='hq');if(base){scene.focus.x=base.x+1.5;scene.focus.z=base.y+1.5;scene.zoom=innerWidth<700?.65:.9;scene.updateCamera();}else scene.home(state);}
function render(){const b=state.battle;if(!b)return;renderSkills();const result=state.network?.result,side=room.role==='host'?'azul':'rojo';$('#duel-title').textContent=(room.role==='host'?room.name:room.remoteName||'Anfitrión')+' vs '+(room.role==='guest'?room.name:room.remoteName||'Invitado');$('#duel-clock').textContent='Tu ejército: '+side+' · '+Math.floor(b.elapsed/60)+' m '+Math.floor(b.elapsed%60)+' s · copia amistosa';$('#duel-result').hidden=!result;if(result){$('#duel-result').textContent=result.winner==='draw'?'Empate':result.winner===room.role?'Victoria en el duelo':'Tu centro de mando ha caído';$('#duel-rematch').hidden=room.role!=='host';}else $('#duel-rematch').hidden=true;
 const list=$('#duel-roster'),units=b.units.filter(own),signature=units.map(u=>u.id+':'+Math.floor(u.hp)+':'+selected.includes(u.id)).join('|');if(list.dataset.signature!==signature){list.dataset.signature=signature;list.replaceChildren(...units.map(u=>{const button=document.createElement('button');button.dataset.unitId=u.id;button.textContent=E.UNITS[u.type].name+' · '+Math.ceil(u.hp);button.classList.toggle('duel-selected',selected.includes(u.id));button.addEventListener('click',event=>{selected=event.shiftKey?[...new Set([...selected,u.id])]:[u.id];render();});return button;}));}for(const u of units){const button=list.querySelector('[data-unit-id="'+u.id+'"]');if(button){button.dataset.x=u.x.toFixed(2);button.dataset.y=u.y.toFixed(2);}}$('#duel-world').dataset.elapsed=b.elapsed.toFixed(2);$('#duel-world').dataset.role=room.role;$('#duel-world').dataset.connected=String(room.channel?.readyState==='open');}
function pick(p){if(!state.battle||!room)return;if(abilityMode&&Number.isFinite(p.x)){room.command({kind:'ability',ids:selected,ability:abilityMode,x:p.x,y:p.y});abilityMode=null;renderSkills();return;}if(p.box){selected=state.battle.units.filter(own).filter(u=>{const q=scene.screen(u.x,u.y,.5);return q.x>=p.box.x1&&q.x<=p.box.x2&&q.y>=p.box.y1&&q.y<=p.box.y2;}).map(u=>u.id);render();return;}const unit=state.battle.units.find(u=>own(u)&&u.id===p.actorId);if(unit&&p.button!==2){selected=p.append?[...new Set([...selected,unit.id])]:[unit.id];render();return;}if(selected.length)room.command({kind:mode,ids:selected,x:p.x,y:p.y});}
function createRoom(){room?.close();const urls=$('#ice-url').value.trim(),iceServers=$('#lan-only').checked?[]:[{urls:urls||'stun:stun.l.google.com:19302',...(urls.startsWith('turn')?{username:$('#ice-user').value,credential:$('#ice-password').value}:{})}];if(urls&&!/^(?:stun|stuns|turn|turns):[^\s]{1,240}$/.test(urls))throw Error('Servidor de conexión no válido.');room=new PeerRoom({roster,name:$('#player-name').value,iceServers,onStatus:text=>{$('#connection-status').textContent=text;},onMessage:message,onState:next=>{const first=state.battle?.kind!=='network';state=next;if(first){selected=[];$('#lobby').hidden=true;center();}render();}});return room;}
async function action(button,work){button.disabled=true;try{await work();}catch{message('No se pudo completar la conexión. Revisa los códigos, la red y la configuración STUN/TURN.');}finally{button.disabled=false;}}
$('#create-room').addEventListener('click',event=>action(event.target,async()=>{const r=createRoom();$('#offer-out').value=await r.createOffer();message('Invitación preparada. Compártela con la otra persona y espera su respuesta.');}));
$('#join-room').addEventListener('click',event=>action(event.target,async()=>{const r=createRoom();$('#answer-out').value=await r.acceptOffer($('#offer-in').value);message('Respuesta preparada. Envíala al anfitrión para que pulse Conectar.');}));
$('#connect-room').addEventListener('click',event=>action(event.target,async()=>{if(!room||room.role!=='host')throw Error('Crea primero una sala.');await room.acceptAnswer($('#answer-in').value);message('Conectando ambos ejércitos…');}));
for(const button of document.querySelectorAll('[data-copy]'))button.addEventListener('click',async()=>{const input=document.getElementById(button.dataset.copy);try{await navigator.clipboard.writeText(input.value);message('Código copiado.');}catch{input.focus();input.select();message('Selecciona y copia el código con el menú del navegador.');}});
$('#lobby-toggle').addEventListener('click',()=>$('#lobby').hidden=!$('#lobby').hidden);$('#close-lobby').addEventListener('click',()=>$('#lobby').hidden=true);$('#leave-room').addEventListener('click',()=>{room?.close();$('#connection-status').textContent='Fuera de la sala';message('La campaña y el ejército principal se conservan.');});$('#duel-home').addEventListener('click',center);$('#duel-select-all').addEventListener('click',()=>{selected=state.battle?.units.filter(own).map(u=>u.id)||[];render();});for(const[kind,id]of[['move','duel-move'],['attack','duel-assault']])$('#'+id).addEventListener('click',()=>{mode=kind;$('#duel-move').setAttribute('aria-pressed',String(kind==='move'));$('#duel-assault').setAttribute('aria-pressed',String(kind==='attack'));});$('#duel-hold').addEventListener('click',()=>{const u=state.battle?.units.find(u=>selected.includes(u.id));if(u)room.command({kind:'hold',ids:selected,x:u.x,y:u.y});});$('#duel-rematch').addEventListener('click',()=>{room?.restart();center();});
addEventListener('pagehide',()=>room?.close());function frame(now){if(now-lastFrame>40){scene.draw(state,{selected});lastFrame=now;}if(now-lastUi>250){render();lastUi=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
